const ui={menu:document.querySelector('#menu'),intro:document.querySelector('#intro'),result:document.querySelector('#result'),start:document.querySelector('#start'),again:document.querySelector('#again'),score:document.querySelector('#score'),against:document.querySelector('#against'),dots:document.querySelector('#dots'),status:document.querySelector('#status'),toast:document.querySelector('#toast'),hint:document.querySelector('#hint'),shoot:document.querySelector('#shoot'),shootLabel:document.querySelector('#shootLabel'),power:document.querySelector('#powerFill')};
let started=false,finished=false,shots=0,goals=0,conceded=0,flight=null,charging=false,power=0,toastTimer=0,keeperTarget=0,keeperDiving=0,lastTime=0;
let move={x:0,y:0},aim={x:0,y:0};let aimTarget={x:0,y:1.55};
const clamp=(v,a,b)=>Math.max(a,Math.min(b,v));
function setStatus(text){ui.status.innerHTML=text}
function showToast(text,type){ui.toast.textContent=text;ui.toast.className=`toast show ${type||''}`;clearTimeout(toastTimer);toastTimer=setTimeout(()=>ui.toast.className='toast',1150)}
function updateDots(){ui.dots.innerHTML='';for(let i=0;i<5;i++){const d=document.createElement('i');d.className='dot '+(i<shots?(i<goals?'done':'miss'):'');ui.dots.appendChild(d)}}
function ballHome(){ball.position.set(player.position.x, .23, player.position.z-1.05);ball.rotation.set(0,0,0);shadowBall.position.x=ball.position.x;shadowBall.position.z=ball.position.z;shadowBall.scale.setScalar(1)}
function resetShot(){flight=null;charging=false;power=0;ui.power.style.height='0%';ui.shoot.classList.remove('charging');ui.shootLabel.textContent='SHOOT';move.x=move.y=0;aim.x=aim.y=0;aimTarget.x=clamp(player.position.x*.48,-2.5,2.5);aimTarget.y=1.55;keeper.position.set(0,0,-21.5);keeper.rotation.set(0,0,0);keeperDiving=0;player.position.z=9;ballHome();setStatus(`ROUND <b>0${Math.min(shots+1,5)}</b> &nbsp;·&nbsp; PLACE YOUR SHOT`)}
function startGame(){started=true;finished=false;shots=goals=conceded=0;ui.score.textContent='0';ui.against.textContent='0';ui.menu.classList.add('hidden');ui.intro.style.display='';ui.result.style.display='none';updateDots();resetShot();playTone(480,.08,'sine',.04)}
function finishGame(){finished=true;ui.menu.classList.remove('hidden');ui.intro.style.display='none';ui.result.style.display='';const champion=goals>=3;document.querySelector('#resultTitle').textContent=champion?'CHAMPIONS!':'FULL TIME';document.querySelector('#resultTitle').style.color=champion?'var(--lime)':'#fff';document.querySelector('#resultText').textContent=champion?`${goals} goals from 5. The cup is yours — what a finish.`:`${goals} goals from 5. The crowd will remember the fight.`}
ui.start.addEventListener('click',startGame);ui.again.addEventListener('click',startGame);
// Lightweight generated sound cues; audio begins only after the player's first gesture.
let audioCtx;function playTone(freq,duration=.12,type='sine',volume=.05){try{audioCtx ||=new (window.AudioContext||window.webkitAudioContext)();const o=audioCtx.createOscillator(),g=audioCtx.createGain();o.type=type;o.frequency.value=freq;g.gain.setValueAtTime(volume,audioCtx.currentTime);g.gain.exponentialRampToValueAtTime(.001,audioCtx.currentTime+duration);o.connect(g);g.connect(audioCtx.destination);o.start();o.stop(audioCtx.currentTime+duration)}catch{}}
function makePad(el,callback){const knob=el.querySelector('.knob');let id=null,rect;function set(e){rect ||=el.getBoundingClientRect();const dx=e.clientX-(rect.left+rect.width/2),dy=e.clientY-(rect.top+rect.height/2),r=rect.width*.31,len=Math.hypot(dx,dy),scale=len>r?r/len:1;const x=dx*scale/r,y=dy*scale/r;knob.style.left=`${50+x*31}%`;knob.style.top=`${50+y*31}%`;callback(x,y)}el.addEventListener('pointerdown',e=>{if(id!==null)return;id=e.pointerId;el.setPointerCapture(id);rect=el.getBoundingClientRect();set(e)});el.addEventListener('pointermove',e=>{if(e.pointerId===id)set(e)});function end(e){if(e.pointerId!==id)return;id=null;rect=null;knob.style.left='50%';knob.style.top='50%';callback(0,0)}el.addEventListener('pointerup',end);el.addEventListener('pointercancel',end)}
makePad(document.querySelector('#moveStick'),(x,y)=>{move.x=x;move.y=y});
// Drag anywhere in the right half of the field to steer shot placement.
renderer.domElement.addEventListener('pointerdown',e=>{if(!started||finished||flight||e.clientX<innerWidth*.48)return;renderer.domElement.setPointerCapture(e.pointerId);aim.x=0;aim.y=0;aim._id=e.pointerId;aim._lastX=e.clientX;aim._lastY=e.clientY});renderer.domElement.addEventListener('pointermove',e=>{if(e.pointerId!==aim._id)return;const dx=e.clientX-aim._lastX,dy=e.clientY-aim._lastY;aim._lastX=e.clientX;aim._lastY=e.clientY;aimTarget.x=clamp(aimTarget.x+dx/innerWidth*12,-3.15,3.15);aimTarget.y=clamp(aimTarget.y-dy/innerHeight*7,.45,2.82)});function aimEnd(e){if(e.pointerId===aim._id)aim._id=null}renderer.domElement.addEventListener('pointerup',aimEnd);renderer.domElement.addEventListener('pointercancel',aimEnd);
// Keyboard support for desktop
const keys={};window.addEventListener('keydown',e=>{keys[e.code]=true;if(['Space','ArrowUp','ArrowDown','ArrowLeft','ArrowRight'].includes(e.code))e.preventDefault();if(e.code==='Space'&&started&&!finished&&!flight&&!charging)beginCharge()});window.addEventListener('keyup',e=>{keys[e.code]=false;if(e.code==='Space'&&charging)kick()});
function beginCharge(){if(!started||finished||flight||charging)return;charging=true;power=0;ui.shoot.classList.add('charging');ui.shootLabel.textContent='RELEASE';playTone(220,.06,'triangle',.03)}
function kick(){if(!charging)return;charging=false;ui.shoot.classList.remove('charging');ui.shootLabel.textContent='SHOOT';shots++;updateDots();const pwr=.57+power*.65;const start=ball.position.clone();const targetX=aimTarget.x+player.position.x*.1;const dx=targetX-start.x,dz=-24-start.z,dist=Math.hypot(dx,dz);const vx=dx/dist*pwr*20,vz=dz/dist*pwr*20;const vy=clamp((aimTarget.y-start.y)/dist*pwr*20+2.5,3.5,10.8);flight={v:new THREE.Vector3(vx,vy,vz),startTime:performance.now(),goalX:targetX,goalY:aimTarget.y,resolved:false};setStatus('SHOT <b>IN FLIGHT</b>');keeperTarget=clamp(targetX*.84+(Math.random()-.5)*1.3,-3.2,3.2);keeperDiving=1;playTone(110,.16,'triangle',.07)}
ui.shoot.addEventListener('pointerdown',e=>{e.preventDefault();ui.shoot.setPointerCapture(e.pointerId);beginCharge()});ui.shoot.addEventListener('pointerup',e=>{e.preventDefault();kick()});ui.shoot.addEventListener('pointercancel',()=>{if(charging)kick()});
function resolveShot(isGoal,keeperSave=false){if(!flight||flight.resolved)return;flight.resolved=true;flight=null;keeperDiving=0;if(isGoal){goals++;ui.score.textContent=goals;showToast('GOAL!','goal');playTone(660,.25,'sine',.08);setStatus('<b>TOP BINS!</b> &nbsp; THE CROWD ERUPTS')}else{conceded++;ui.against.textContent=conceded;showToast(keeperSave?'SAVED!':'WIDE!','miss');playTone(keeperSave?165:95,.2,'triangle',.06);setStatus(keeperSave?'<b>DENIED.</b> &nbsp; THE KEEPER READ IT':'<b>NO!</b> &nbsp; FIND THE TARGET')}
setTimeout(()=>{if(shots>=5){finishGame()}else resetShot();updateDots()},1300)}
function update(dt,time){if(!started||finished)return;
if(!flight){let mx=move.x+(keys.KeyA||keys.ArrowLeft?-1:0)+(keys.KeyD||keys.ArrowRight?1:0),my=move.y+(keys.KeyW||keys.ArrowUp?-1:0)+(keys.KeyS||keys.ArrowDown?1:0);const length=Math.hypot(mx,my);if(length>1){mx/=length;my/=length}player.position.x=clamp(player.position.x+mx*dt*5.2,-6.8,6.8);player.position.z=clamp(player.position.z-my*dt*3.2,6.5,12.5);player.rotation.y=mx*.2;ballHome();if(charging){power=Math.min(1,power+dt*.44);ui.power.style.height=`${power*100}%`}}
else{const t=(time-flight.startTime)/1000, f=flight;ball.position.x+=f.v.x*dt;ball.position.z+=f.v.z*dt;ball.position.y+=f.v.y*dt;f.v.y-=9.8*dt;ball.rotation.x+=dt*9;ball.rotation.z+=dt*4;shadowBall.position.set(ball.position.x,.025,ball.position.z);const h=clamp(1-ball.position.y/8,.35,1);shadowBall.scale.set(h,h,h);keeper.position.x+=(keeperTarget-keeper.position.x)*Math.min(1,dt*3.5);keeper.position.y=keeperDiving?Math.sin(Math.min(t*3.8,1.3))*-.25:0;keeper.rotation.z=keeperDiving?clamp((keeperTarget-keeper.position.x)*-.16,-.45,.45):0;
const inGoalZone=ball.position.z < -21.6;
if(inGoalZone){const inside=Math.abs(ball.position.x)<3.54&&ball.position.y<3.02&&ball.position.y>.12;const kx=keeper.position.x,kReach=1.02+(ball.position.y<1.3?.5:0),keeperCanReach=Math.abs(ball.position.x-kx)<kReach&&ball.position.y<2.6&&ball.position.y>.22;if(inside&&keeperCanReach){resolveShot(false,true)}else if(inside){resolveShot(true)}else resolveShot(false)}
if(ball.position.y<.23&&ball.position.z>-21.5){ball.position.y=.23;f.v.y=Math.abs(f.v.y)*.36;if(Math.abs(f.v.y)<1.2)f.v.y=3;f.v.x*=.8;f.v.z*=.96}if(ball.position.z<-26||t>3.5)resolveShot(false);}
// Soft chase camera keeps the ball, player and goal readable on every screen.
const desired=new THREE.Vector3(player.position.x*.4,7.2,19.5);camera.position.lerp(desired,1-Math.exp(-dt*2.7));camera.lookAt(player.position.x*.22,1.15,-7.2);
}
function resize(){camera.aspect=innerWidth/innerHeight;camera.fov=innerWidth<650?47:42;camera.updateProjectionMatrix();renderer.setPixelRatio(Math.min(devicePixelRatio,1.8));renderer.setSize(innerWidth,innerHeight)}window.addEventListener('resize',resize);window.addEventListener('orientationchange',()=>setTimeout(resize,150));
resetShot();updateDots();function loop(time){requestAnimationFrame(loop);const dt=Math.min(.04,(time-lastTime)/1000||.016);lastTime=time;update(dt,time);renderer.render(scene,camera)}requestAnimationFrame(loop);
</script>
</body>
</html>

